<section class="card"><h2>Создать технологический маршрут</h2><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="route_create"><input type="hidden" name="back" value="routes"><label>Название маршрута</label><input name="name" required><div id="route-builder"></div><template id="route-template"><fieldset><label>Название этапа</label><input data-step-name required><label>Допустимые станки (можно несколько)</label><select data-step-machines multiple required><?php foreach($machines as $m):?><option value="<?=$m['id']?>"><?=h($m['name'])?></option><?php endforeach;?></select><button type="button" data-remove>Удалить этап</button></fieldset></template><button type="button" id="add-step">+ Этап</button><button class="primary">Сохранить маршрут</button></form></section><section class="card"><h2>Маршруты</h2><?php foreach($routes as $r):?><h3><?=h($r['name'])?></h3><ol><?php foreach(query('SELECT * FROM route_steps WHERE route_id=? ORDER BY position',[$r['id']]) as $s):?><li><?=h($s['name'])?> — <?=h(implode(', ',array_map(fn($id)=>first('SELECT name FROM machines WHERE id=?',[$id])['name']??'Архив',json_decode($s['machines'],true))))?></li><?php endforeach;?></ol><?php endforeach;?></section>